<?php
function supportPerformance($db,$identity,$input)
{
    if(!$identity['superadmin'])throw new InvalidArgumentException('Panel de rendimiento reservado al superadmin.');
    $zone=new DateTimeZone('America/Lima');$from=$input['from']??date('Y-m-01');$to=$input['to']??date('Y-m-d');
    foreach([$from,$to] as $date){$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',(string)$date,$zone);if(!$parsed||$parsed->format('Y-m-d')!==$date)throw new InvalidArgumentException('Rango de fechas inválido.');}
    $start=new DateTimeImmutable($from,$zone);$end=(new DateTimeImmutable($to,$zone))->modify('+1 day');if($end<=$start||$start->diff($end)->days>366)throw new InvalidArgumentException('Consulta hasta un año de rendimiento.');
    $a=$start->format('Y-m-d H:i:s');$b=$end->format('Y-m-d H:i:s');$user=supportText($input['user']??'',255,false);$team=[];$daily=[];$evidence=[];$evidenceCount=0;
    $principal=function($id,$name)use(&$team){if(!isset($team[$id]))$team[$id]=['id'=>(int)$id,'user'=>$name,'assigned'=>0,'pending'=>0,'attended'=>0,'resolved_events'=>0,'work_minutes'=>0,'worklogs'=>0,'response_count'=>0,'response_minutes'=>0,'resolution_count'=>0,'resolution_minutes'=>0,'ratings'=>0,'rating_sum'=>0];};
    $people=supportQuery($db,"SELECT DISTINCT p.id,p.external_user_id FROM support_principals p JOIN support_memberships m ON m.principal_id=p.id WHERE m.role IN ('technician','supervisor','superadmin')".($user!==''?' AND p.external_user_id=?':''),$user!==''?[$user]:[])->fetchAll(PDO::FETCH_ASSOC);foreach($people as $p)$principal($p['id'],$p['external_user_id']);
    $joins=' FROM support_tickets t JOIN support_tenants tenant ON tenant.id=t.tenant_id AND tenant.active=1 JOIN support_installations inst ON inst.id=tenant.installation_id AND inst.active=1 ';
    $validated=supportValidatedSql();$statusSql="CASE WHEN t.status='closed' AND NOT (".$validated.") THEN 'resolved' ELSE t.status END";
    $tickets=supportQuery($db,'SELECT t.technician_id id,p.external_user_id user,'. $statusSql .' status,COUNT(*) total'.$joins.' JOIN support_principals p ON p.id=t.technician_id WHERE t.created_at>=? AND t.created_at<?'.($user!==''?' AND p.external_user_id=?':'').' GROUP BY t.technician_id,p.external_user_id,t.status,('.$validated.')',array_merge([$a,$b],$user!==''?[$user]:[]))->fetchAll(PDO::FETCH_ASSOC);
    foreach($tickets as $t){$principal($t['id'],$t['user']);$team[$t['id']]['assigned']+=(int)$t['total'];if($t['status']==='closed')$team[$t['id']]['attended']+=(int)$t['total'];elseif($t['status']!=='cancelled')$team[$t['id']]['pending']+=(int)$t['total'];}
    $event=function($day,$id,$name,$field,$amount)use(&$daily,$principal,&$team){$principal($id,$name);$team[$id][$field]+=$amount;$key=$day.':'.$id;if(!isset($daily[$key]))$daily[$key]=['date'=>$day,'user'=>$name,'work_minutes'=>0,'response_count'=>0,'resolved_events'=>0];if(isset($daily[$key][$field]))$daily[$key][$field]+=$amount;};
    $log=supportQuery($db,'SELECT w.*,t.code,p.external_user_id user'.$joins.' JOIN support_worklogs w ON w.ticket_id=t.id AND w.tenant_id=t.tenant_id JOIN support_principals p ON p.id=w.technician_id WHERE w.started_at<? AND w.ended_at>?'.($user!==''?' AND p.external_user_id=?':'').' ORDER BY w.ended_at DESC,w.id DESC',array_merge([$b,$a],$user!==''?[$user]:[]));
    while($w=$log->fetch(PDO::FETCH_ASSOC)){$left=max($start->getTimestamp(),(new DateTimeImmutable($w['started_at'],$zone))->getTimestamp());$right=min($end->getTimestamp(),(new DateTimeImmutable($w['ended_at'],$zone))->getTimestamp());$minutes=max(0,$right-$left)/60;$principal($w['technician_id'],$w['user']);$team[$w['technician_id']]['worklogs']++;while($left<$right){$date=(new DateTimeImmutable('@'.$left))->setTimezone($zone);$stop=min($right,$date->modify('tomorrow')->setTime(0,0)->getTimestamp());$event($date->format('Y-m-d'),$w['technician_id'],$w['user'],'work_minutes',($stop-$left)/60);$left=$stop;}$evidenceCount++;if(count($evidence)<2000)$evidence[]=['ticket_id'=>(int)$w['ticket_id'],'code'=>$w['code'],'user'=>$w['user'],'date'=>$w['ended_at'],'minutes'=>round($minutes,2),'description'=>$w['description']];}
    $responses=supportQuery($db,'SELECT l.actor_id id,p.external_user_id user,l.created_at,TIMESTAMPDIFF(SECOND,t.created_at,l.created_at)/60 minutes'.$joins." JOIN support_audit_logs l ON l.entity_id=t.id AND l.tenant_id=t.tenant_id AND l.action='first_response' JOIN support_principals p ON p.id=l.actor_id WHERE l.created_at>=? AND l.created_at<?".($user!==''?' AND p.external_user_id=?':''),array_merge([$a,$b],$user!==''?[$user]:[]))->fetchAll(PDO::FETCH_ASSOC);
    foreach($responses as $r){$event(substr($r['created_at'],0,10),$r['id'],$r['user'],'response_count',1);$team[$r['id']]['response_minutes']+=max(0,(float)$r['minutes']);}
    $solutions=supportQuery($db,'SELECT h.actor_id id,p.external_user_id user,h.created_at,TIMESTAMPDIFF(SECOND,t.created_at,h.created_at)/60 minutes'.$joins." JOIN support_ticket_status_history h ON h.ticket_id=t.id AND h.tenant_id=t.tenant_id AND h.next_status='resolved' JOIN support_principals p ON p.id=h.actor_id WHERE h.created_at>=? AND h.created_at<?".($user!==''?' AND p.external_user_id=?':''),array_merge([$a,$b],$user!==''?[$user]:[]))->fetchAll(PDO::FETCH_ASSOC);
    foreach($solutions as $r){$event(substr($r['created_at'],0,10),$r['id'],$r['user'],'resolved_events',1);$team[$r['id']]['resolution_count']++;$team[$r['id']]['resolution_minutes']+=max(0,(float)$r['minutes']);}
    $ratings=supportQuery($db,'SELECT s.technician_id id,p.external_user_id user,COUNT(*) total,SUM((s.speed+s.treatment+s.solution)/3.0) score'.$joins.' JOIN support_satisfaction_surveys s ON s.ticket_id=t.id AND s.tenant_id=t.tenant_id JOIN support_principals p ON p.id=s.technician_id WHERE s.created_at>=? AND s.created_at<?'.($user!==''?' AND p.external_user_id=?':'').' GROUP BY s.technician_id,p.external_user_id',array_merge([$a,$b],$user!==''?[$user]:[]))->fetchAll(PDO::FETCH_ASSOC);
    foreach($ratings as $r){$principal($r['id'],$r['user']);$team[$r['id']]['ratings']=(int)$r['total'];$team[$r['id']]['rating_sum']=(float)$r['score'];}
    $legacy=(int)supportQuery($db,'SELECT COUNT(*)'.$joins." WHERE t.first_response_at>=? AND t.first_response_at<? AND NOT EXISTS(SELECT 1 FROM support_audit_logs l WHERE l.tenant_id=t.tenant_id AND l.entity_id=t.id AND l.action='first_response')".($user!==''?' AND t.technician_id IN(SELECT id FROM support_principals WHERE external_user_id=?)':''),array_merge([$a,$b],$user!==''?[$user]:[]))->fetchColumn();
    foreach($team as &$p){$p['work_minutes']=round($p['work_minutes'],2);$p['response_average']=$p['response_count']?round($p['response_minutes']/$p['response_count'],2):null;$p['resolution_average']=$p['resolution_count']?round($p['resolution_minutes']/$p['resolution_count'],2):null;$p['rating']=$p['ratings']?round($p['rating_sum']/$p['ratings'],2):null;}unset($p);
    $reviews=supportQuery($db,"SELECT l.id,l.created_at,p.external_user_id reviewer,l.metadata_json FROM support_audit_logs l JOIN support_principals p ON p.id=l.actor_id WHERE l.action='performance_review' AND JSON_UNQUOTE(JSON_EXTRACT(l.metadata_json,'$.from'))=? AND JSON_UNQUOTE(JSON_EXTRACT(l.metadata_json,'$.to'))=?".($user!==''?" AND JSON_UNQUOTE(JSON_EXTRACT(l.metadata_json,'$.user'))=?":'').' ORDER BY l.id DESC LIMIT 100',array_merge([$from,$to],$user!==''?[$user]:[]))->fetchAll(PDO::FETCH_ASSOC);foreach($reviews as &$r){$r['review']=json_decode($r['metadata_json'],true);unset($r['metadata_json']);}unset($r);
    return ['from'=>$from,'to'=>$to,'team'=>array_values($team),'daily'=>array_values($daily),'evidence'=>$evidence,'evidence_total'=>$evidenceCount,'evidence_limited'=>$evidenceCount>2000,'unattributed_responses'=>$legacy,'reviews'=>$reviews,'satisfaction'=>supportSatisfaction($db,$identity,$input)];
}

function supportPerformanceReview($db,$identity,$input)
{
    if(!$identity['superadmin'])throw new InvalidArgumentException('Evaluación reservada al superadmin.');
    $target=(int)($input['principal']??0);$report=supportPerformance($db,$identity,$input);$person=null;foreach($report['team'] as $p)if($p['id']===$target)$person=$p;if(!$person)throw new InvalidArgumentException('Selecciona un responsable del reporte.');
    $score=filter_var($input['score']??null,FILTER_VALIDATE_INT);if(!$score||$score<1||$score>5)throw new InvalidArgumentException('Califica entre 1 y 5.');
    $proposal=$input['proposal']??'';if(!in_array($proposal,['development','recognition','raise_review','promotion_review'],true))throw new InvalidArgumentException('Selecciona una propuesta válida.');
    $data=['principal'=>$target,'user'=>$person['user'],'from'=>$report['from'],'to'=>$report['to'],'score'=>$score,'proposal'=>$proposal,'reason'=>supportText($input['reason']??'',5000),'criteria'=>supportText($input['criteria']??'',3000),'indicators'=>$person];
    supportQuery($db,"INSERT INTO support_audit_logs(tenant_id,actor_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,'performance_review','performance',NULL,?,?)",[$identity['tenant'],$identity['principal'],json_encode($data,JSON_UNESCAPED_UNICODE),supportNow()]);return ['ok'=>true];
}
